-- Native owners remain independent of every enterprise connection.
CREATE TABLE enterprise_connections(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),protocol TEXT NOT NULL CHECK(protocol IN ('oidc','saml')),issuer TEXT NOT NULL,config_json TEXT NOT NULL,secret_cipher TEXT,scim_hash TEXT,enabled INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE enterprise_principals(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES enterprise_connections(id),project_id TEXT NOT NULL REFERENCES projects(id),external_id TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),user_name TEXT NOT NULL,display_name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(connection_id,external_id),UNIQUE(project_id,user_id));
CREATE TABLE enterprise_states(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES enterprise_connections(id),version INTEGER NOT NULL,browser_hash TEXT NOT NULL,verifier TEXT NOT NULL,nonce TEXT NOT NULL,request_id TEXT,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER);
CREATE TABLE enterprise_sessions(token_hash TEXT PRIMARY KEY,principal_id TEXT NOT NULL REFERENCES enterprise_principals(id),connection_version INTEGER NOT NULL,authenticated_at INTEGER NOT NULL);
CREATE INDEX enterprise_principal_user ON enterprise_principals(user_id,project_id);
CREATE INDEX enterprise_state_expiry ON enterprise_states(expires_at);
CREATE TRIGGER enterprise_principal_active_insert BEFORE INSERT ON enterprise_principals WHEN NEW.active=1 AND NOT EXISTS(SELECT 1 FROM enterprise_connections WHERE id=NEW.connection_id AND project_id=NEW.project_id AND enabled=1) BEGIN SELECT RAISE(ABORT,'identity_connection_disabled'); END;
CREATE TRIGGER enterprise_principal_active_update BEFORE UPDATE OF active ON enterprise_principals WHEN NEW.active=1 AND NOT EXISTS(SELECT 1 FROM enterprise_connections WHERE id=NEW.connection_id AND project_id=NEW.project_id AND enabled=1) BEGIN SELECT RAISE(ABORT,'identity_connection_disabled'); END;
